function isAnagram(s, t) {
  if (s.length !== t.length) return false;
  const sorted = (x) => [...x].sort().join("");
  return sorted(s) === sorted(t);             // anagrams sort to the same string
}

boolean isAnagram(String s, String t) {
    if (s.length() != t.length()) return false;
    char[] a = s.toCharArray(), b = t.toCharArray();
    Arrays.sort(a);
    Arrays.sort(b);
    return Arrays.equals(a, b);                  // anagrams sort to the same letters
}

bool isAnagram(string s, string t) {             // taken by value: we sort our own copies
    sort(s.begin(), s.end());
    sort(t.begin(), t.end());
    return s == t;                               // anagrams sort to the same string
}

function isAnagram(s, t) {
  if (s.length !== t.length) return false;   // different lengths can't match
  const count = new Array(26).fill(0);
  for (let i = 0; i < s.length; i++) {
    count[s.charCodeAt(i) - 97]++;            // s adds one
    count[t.charCodeAt(i) - 97]--;            // t takes one away
  }
  return count.every((c) => c === 0);         // every letter balanced out?
}

def is_anagram(s, t):
    if len(s) != len(t):
        return False                      # different lengths can't match
    count = [0] * 26
    for a, b in zip(s, t):
        count[ord(a) - ord("a")] += 1     # s adds one
        count[ord(b) - ord("a")] -= 1     # t takes one away
    return all(c == 0 for c in count)     # every letter balanced out?

boolean isAnagram(String s, String t) {
    if (s.length() != t.length()) return false;  // different lengths can't match
    int[] count = new int[26];
    for (int i = 0; i < s.length(); i++) {
        count[s.charAt(i) - 'a']++;              // s adds one
        count[t.charAt(i) - 'a']--;              // t takes one away
    }
    for (int c : count) if (c != 0) return false;
    return true;                                 // every letter balanced out
}

bool isAnagram(string s, string t) {
    if (s.size() != t.size()) return false;      // different lengths can't match
    int count[26] = {0};
    for (size_t i = 0; i < s.size(); i++) {
        count[s[i] - 'a']++;                     // s adds one
        count[t[i] - 'a']--;                     // t takes one away
    }
    for (int c : count) if (c != 0) return false;
    return true;                                 // every letter balanced out
}
